function r17Baixar(nome,txt,mime){try{const b=new Blob([txt],{type:mime||'text/csv;charset=utf-8'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=nome;a.style.display='none';document.body.appendChild(a);a.click();setTimeout(()=>{try{URL.revokeObjectURL(u);a.remove()}catch(e){}},1500);return true}catch(e){return false}}
/* Separador ponto e vírgula e BOM: o Excel em português abre com acentos e colunas certas */
const r17Csv=linhas=>'﻿'+linhas.map(l=>l.map(v=>{const s=String(v??'');return /[;"\r\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}).join(';')).join('\r\n');
