function cxRepasseLinhas(){return clAgendaHoje().filter(a=>a.prof&&['finalizado','em atendimento'].includes(a.sit)).map(a=>({prof:a.prof,pac:a.pac,h:a.h,conv:a.conv||'Particular',itens:a.itens.map(c=>clProcNome(c)),v:a.itens.reduce((s,c)=>s+clRepasse(c),0),unid:cxRepUnidDe(a)}))}
/* Agrupa por médico e unidade (o mesmo médico pode atender em duas unidades no dia) */
function cxRepasseDia(){const por={};cxRepasseLinhas().forEach(l=>{const k=l.prof+'|'+l.unid;const g=por[k]||(por[k]={k,prof:l.prof,unid:l.unid,at:0,itens:[],v:0,linhas:[]});g.at++;g.itens.push(...l.itens);g.v+=l.v;g.linhas.push(l)});return Object.values(por).sort((a,b)=>a.unid-b.unid||PROF(a.prof).n.localeCompare(PROF(b.prof).n))}
const cxRepPg=k=>{const p=CX_REP_PAGO[k]||CX_REP_PAGO[String(k).split('|')[0]];return p&&typeof p==='object'?p:p?{h:p,op:'não registrado',orig:'não registrado'}:null};
const cxRepUnidChips=(us,oc)=>us.length>1?`<div class="filters" style="margin:4px 0 8px">${chip('Todas as unidades',!CX_REP_UNID,`CX_REP_UNID='';${oc}`)}${us.map(u=>chip(esc(unidNome(u)),CX_REP_UNID===String(u),`CX_REP_UNID='${u}';${oc}`)).join('')}</div>`:'';
function cxRepasseCard(){const todos=cxRepasseDia(),us=[...new Set(todos.map(x=>x.unid))],l=CX_REP_UNID?todos.filter(x=>String(x.unid)===CX_REP_UNID):todos,tot=l.reduce((s,x)=>s+x.v,0),pago=l.filter(x=>cxRepPg(x.k)).reduce((s,x)=>s+x.v,0);
 return `<div class="card" style="margin-top:14px" id="cxRepasse"><h3>Repasse da produção médica de hoje ${info('Valor a pagar a cada médico pelo que atendeu hoje, pela regra de repasse do cadastro do profissional, separado por unidade. Pagar registra a saída com quem pagou, a hora e de qual caixa (ou da conta bancária) o dinheiro saiu.')}</h3><div class="sub">${l.length} médico(s) · total ${fmt(tot)} · já pago ${fmt(pago)}</div>
 ${cxRepUnidChips(us,'reView()')}
 ${tabela(['Médico','Unidade','Pacientes','Procedimentos','Valor a pagar','Pagamento'],l.map(x=>{const p=cxRepPg(x.k);return `<tr data-det="0">${td('Médico',esc(PROF(x.prof).n))}${td('Unidade',esc(unidNome(x.unid)))}${td('Pacientes',String(x.at))}${td('Procedimentos',esc([...new Set(x.itens)].join(', ')))}${td('Valor a pagar',`<b>${fmt(x.v)}</b>`)}${td('Pagamento',p?`<span class="badge ok">Pago ${esc(p.h)}</span><small class="tl" style="display:block">por ${esc(p.op)} · saiu de: ${esc(p.orig)}</small>`:x.v?`<button class="btn sm sec" onclick="cxRepPagar('${x.k}')">Pagar</button>`:'<span class="tl">sem repasse</span>')}</tr>`}),'Nenhum médico atendeu hoje ainda')}
 <div class="row" style="margin-top:10px"><button class="btn sm sec" onclick="cxRepRel()">${I.print} Relatório para o médico assinar (PDF)</button></div></div>`}
function cxRepPagar(k){const x=cxRepasseDia().find(y=>y.k===k);if(!x)return;const abertos=CAIXAS.filter(c=>!c.naoAberto&&!c.fechado).sort((a,b)=>(b.unid===x.unid)-(a.unid===x.unid));const padrao=PERFIL==='recepcao'&&abertos.some(c=>c.u===CAIXA_EU)?CAIXA_EU:(abertos.find(c=>c.unid===x.unid)||{}).u;
 openModal(`${mh('Pagar repasse · '+esc(PROF(x.prof).n))}<div class="mb"><p>Registrar o pagamento de <b>${fmt(x.v)}</b> a <b>${esc(PROF(x.prof).n)}</b>, referente a ${x.at} paciente(s) atendido(s) hoje na ${esc(unidNome(x.unid))}.</p>
 <div class="formgrid"><div class="field"><label for="cxRpOrig">De onde sai o dinheiro <span class="req">*</span> ${info('Se sair de um caixa, entra como sangria com a finalidade "Pagamento de repasse médico" e aparece no fechamento desse caixa.')}</label><select class="in" id="cxRpOrig">${abertos.map(c=>`<option value="caixa:${c.u}" ${c.u===padrao?'selected':''}>Caixa de ${esc(c.u)} · ${esc(unidNome(c.unid))} (gaveta: ${fmt(regDe(c,'Dinheiro'))})</option>`).join('')}<option value="banco" ${padrao?'':'selected'}>Conta bancária da clínica (Pix ou transferência)</option></select></div>
 <div class="field"><label>Operador que paga</label><input class="in" value="${esc(cxOperador())}" disabled></div></div>
 <p class="tl">Fica registrado quem pagou, a hora e a origem do dinheiro. O relatório para o médico assinar sai pelo botão do quadro de repasse.</p></div>
 <div class="mf"><button class="btn ghost" onclick="closeModal()">Cancelar</button><button class="btn" onclick="cxRepPagarOk('${x.k}')">Registrar pagamento</button></div>`)}
function cxRepPagarOk(k){const x=cxRepasseDia().find(y=>y.k===k);if(!x)return;const o=($('#cxRpOrig')||{}).value||'banco',op=cxOperador(),h=hhmm(new Date());let orig='Conta bancária (Pix ou transferência)';
 if(o.startsWith('caixa:')){const c=CAIXAS.find(z=>z.u===o.slice(6));if(!c){toast('Escolha um caixa aberto','warn');return}if(x.v>regDe(c,'Dinheiro')){toast(`Não há ${fmt(x.v)} em dinheiro na gaveta de ${c.u}. Escolha outro caixa ou a conta bancária`,'warn');return}
  c.sang.push({h,v:x.v,q:op,fim:'Pagamento de repasse médico',desc:'Repasse de hoje a '+PROF(x.prof).n});orig='Caixa de '+c.u+' ('+unidNome(c.unid)+')'}
 CX_REP_PAGO[k]={h,op,orig};closeModal();reView();toast(`Repasse de ${fmt(x.v)} registrado: pago por ${op}, saiu de ${orig}`)}
function cxRepRel(){const todos=cxRepasseDia(),us=[...new Set(todos.map(x=>x.unid))],l=CX_REP_UNID?todos.filter(x=>String(x.unid)===CX_REP_UNID):todos,tot=l.reduce((s,x)=>s+x.v,0),hoje=dmy(iso(typeof HOJE!=='undefined'?HOJE:new Date()));
 const blocos=[...new Set(l.map(x=>x.unid))].map(u=>{const g=l.filter(x=>x.unid===u),st=g.reduce((s,x)=>s+x.v,0);return `<h4 style="margin-top:14px">${esc(unidNome(u))}</h4>${g.map(x=>{const p=cxRepPg(x.k),pr=PROF(x.prof);return `<div class="cx-rep-med"><div class="row" style="justify-content:space-between"><b>${esc(pr.n)}</b><span class="tl">${esc(pr.cons||'')} · regra: ${esc(pr.repasse||'—')}</span></div>
 <div class="tablewrap" style="border-radius:12px"><table><thead><tr><th>Hora</th><th>Paciente</th><th>Procedimento</th><th>Convênio</th><th style="text-align:right">Valor do repasse</th></tr></thead><tbody>${x.linhas.map(y=>`<tr data-det="0"><td>${esc(y.h)}</td><td>${esc(y.pac)}</td><td>${esc(y.itens.join(', '))}</td><td>${esc(y.conv)}</td><td style="text-align:right">${fmt(y.v)}</td></tr>`).join('')}<tr data-det="0" style="font-weight:800"><td colspan="4">Total a pagar a ${esc(pr.n)}</td><td style="text-align:right">${fmt(x.v)}</td></tr></tbody></table></div>
 <p style="margin-top:6px">${p?`<b>Pago às ${esc(p.h)}</b> por ${esc(p.op)} · dinheiro retirado de: <b>${esc(p.orig)}</b>`:'<b>Ainda não pago.</b> Ao pagar, registre no caixa para constar aqui de onde saiu o dinheiro.'}</p>
 <div class="ass"><div>${esc(pr.n)} · ${esc(pr.cons||'')}<br>Recebi o valor acima</div><div>${p?esc(p.op):'Operador(a)'} · quem pagou</div></div></div>`}).join('')}<p style="text-align:right;margin-top:8px"><b>Subtotal da unidade: ${fmt(st)}</b></p>`}).join('');
 openModal(`${mh('Relatório de repasse médico')}<div class="mb rel">
 <div class="row rel-cab" style="justify-content:space-between"><div><h2>Repasse da produção médica</h2><span style="color:var(--fg2)">${CX_REP_UNID?esc(unidNome(+CX_REP_UNID)):'Todas as unidades'} · ${hoje}</span></div><img class="rel-logo" src="logo-deovita.png" alt="DeoVita Clínicas"></div>
 <div class="meta"><span>Data: ${hoje}</span><span>Gerado às ${hhmm(new Date())} por ${esc(cxOperador())}</span><span>Médicos: ${l.length}</span><span>Pacientes: ${l.reduce((s,x)=>s+x.at,0)}</span></div>
 ${blocos||'<p class="tl">Nenhum médico com atendimento finalizado hoje.</p>'}
 <div class="tablewrap" style="border-radius:12px;margin-top:12px"><table><tbody><tr data-det="0" style="font-weight:800"><td>Montante final do repasse</td><td style="text-align:right">${fmt(tot)}</td></tr><tr data-det="0"><td>Já pago</td><td style="text-align:right">${fmt(l.filter(x=>cxRepPg(x.k)).reduce((s,x)=>s+x.v,0))}</td></tr></tbody></table></div>
 <p class="tl" style="margin-top:10px">Documento interno e confidencial: traz nomes de pacientes e procedimentos só para conferência do repasse (LGPD, art. 6º, III, e art. 11). Guarde com o financeiro; não envie por WhatsApp nem por e-mail aberto.</p>
 </div><div class="mf mf-fixo">${us.length>1?`<select class="in" style="width:auto" aria-label="Unidade do relatório" onchange="CX_REP_UNID=this.value;cxRepRel()"><option value="">Todas as unidades</option>${us.map(u=>`<option value="${u}" ${CX_REP_UNID===String(u)?'selected':''}>${esc(unidNome(u))}</option>`).join('')}</select>`:''}<button class="btn ghost" onclick="closeModal()">Fechar</button><button class="btn" onclick="toast('Na janela de impressão, escolha Salvar como PDF');window.print()">${I.dl} Baixar PDF</button></div>`,'wide')}

/* ---------- Caixas por operador: filtro por unidade (nota 465) ---------- */
let CX_GRID_UNID='';
{const _v=VIEWS.caixa;VIEWS.caixa=function(){const h=_v.apply(this,arguments);if(PERFIL==='recepcao')return h;const ini='<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(360px,1fr))">',a=h.indexOf(ini),b=h.indexOf('<div class="card" style="margin-top:14px" id="cxRepasse">');if(a<0||b<a)return h;
 const todos=PERFIL==='gestor'?CAIXAS.filter(c=>c.unid===14):CAIXAS,us=[...new Set(todos.map(c=>c.unid))].sort((x,y)=>x-y);if(CX_GRID_UNID&&!us.includes(+CX_GRID_UNID))CX_GRID_UNID='';const l=CX_GRID_UNID?todos.filter(c=>String(c.unid)===CX_GRID_UNID):todos;
 const barra=us.length>1?`<div class="card cx-grid-f" style="margin-top:14px"><div class="row" style="justify-content:space-between;align-items:center;gap:8px"><h3 style="margin:0">Caixas por operador ${info('Cada caixa aberto hoje, com o que atendeu e recebeu. Filtre pela unidade para ver só os caixas dela.')}</h3><span class="tl">${l.length} de ${todos.length} caixas</span></div><div class="filters" style="margin-top:8px">${chip('Todas as unidades',!CX_GRID_UNID,`CX_GRID_UNID='';reView()`)}${us.map(u=>chip(esc(unidNome(u)),CX_GRID_UNID===String(u),`CX_GRID_UNID='${u}';reView()`)).join('')}</div></div>`:'';
 return h.slice(0,a)+barra+ini+l.map(c=>cardCaixa(c)).join('')+'</div>'+h.slice(b)}}

