/* ---------- Filtros em A receber e A pagar: período, tipo de conta, categoria e situação (nota 484) ---------- */
const FN_PER=[['todos','Todo o período'],['venc','Só vencidas'],['7d','Vencem em 7 dias'],['out','Outubro de 2026'],['nov','Novembro de 2026'],['dez','Dezembro de 2026'],['pers','Personalizado (escolher datas)']];
const FN_FL={};const fnFl=t=>FN_FL[t]||(FN_FL[t]={per:'todos',de:'',ate:'',tipo:'',cat:'',sit:''});
function fnFlSet(t,k,v){fnFl(t)[k]=v;if(k==='per'&&v==='pers'){const f=fnFl(t);if(!f.de)f.de='2026-11-01';if(!f.ate)f.ate='2026-11-30'}reView()}
function fnFlLimpar(t){FN_FL[t]={per:'todos',de:'',ate:'',tipo:'',cat:'',sit:''};reView()}
function fnFlPasso(c,f){const d=fnVencIso(c);if(f.per==='venc'&&!(c.s==='Vencido'||(d&&d<FN_REF&&c.s!=='Paga')))return false;if(f.per==='7d'){const lim=iso(new Date(new Date(FN_REF+'T12:00:00').getTime()+7*864e5));if(!d||d<FN_REF||d>lim)return false}
 if(['out','nov','dez'].includes(f.per)&&(!d||d.slice(0,7)!=='2026-'+{out:'10',nov:'11',dez:'12'}[f.per]))return false;if(f.per==='pers'&&(!d||(f.de&&d<f.de)||(f.ate&&d>f.ate)))return false;
 if(f.tipo&&c.tipo!==f.tipo)return false;if(f.cat&&c.cat!==f.cat)return false;if(f.sit&&fnSit(c)!==f.sit)return false;return true}
const fnFiltradas=t=>CONTAS.map((c,i)=>[c,i]).filter(([c])=>c.t===t&&fnFlPasso(c,fnFl(t)));
function fnFiltroBar(t,l){const f=fnFl(t),base=CONTAS.filter(c=>c.t===t),tipos=[...new Set(base.map(c=>c.tipo))].sort(),cats=[...new Set(base.map(c=>c.cat))].sort(),sits=[...new Set(base.map(fnSit))].sort(),ativo=f.per!=='todos'||f.tipo||f.cat||f.sit;
 const sel=(k,lab,ops)=>`<label class="fn-f"><span>${lab}</span><select class="in" aria-label="${lab}" onchange="fnFlSet('${t}','${k}',this.value)">${ops.map(([v,x])=>`<option value="${esc(v)}" ${f[k]===v?'selected':''}>${esc(x)}</option>`).join('')}</select></label>`;
 return `<div class="filters fn-filtros">${sel('per','Período (vencimento)',FN_PER)}${f.per==='pers'?`<label class="fn-f"><span>De</span><input class="in" type="date" value="${f.de}" aria-label="De" onchange="fnFlSet('${t}','de',this.value)"></label><label class="fn-f"><span>Até</span><input class="in" type="date" value="${f.ate}" aria-label="Até" onchange="fnFlSet('${t}','ate',this.value)"></label>`:''}${sel('tipo','Tipo de conta',[['','Todos os tipos'],...tipos.map(x=>[x,x])])}${sel('cat','Categoria',[['','Todas as categorias'],...cats.map(x=>[x,planoNome(x)])])}${sel('sit','Situação',[['','Todas'],...sits.map(x=>[x,x])])}${ativo?`<button class="btn sm ghost" onclick="fnFlLimpar('${t}')">Limpar filtros</button>`:''}<span class="tl" style="margin-left:auto">${l.length} de ${base.length} contas · ${fmt(l.reduce((s,[c])=>s+c.v,0))}</span></div>`}

/* ---------- Cards com o valor já pago e já recebido (nota 503) ---------- */
